#!/bin/zsh
# Local development build of ChocoEdit.app and the chocoprobe tool (this
# Mac's architecture only). Command Line Tools are enough, no Xcode needed.
# To ship a release to the in-app updater, use ./release.sh instead.
set -e
cd "$(dirname "$0")"
VERSION=$(cat VERSION)
BUILT=$(date "+%b %d, %H:%M")
REPO="${REPO:-jonpikereally/ChocoEdit}"
FEED="${UPDATE_FEED-https://raw.githubusercontent.com/$REPO/main/updates/latest.json}"
cat > Sources/ChocoEdit/Version.swift <<SWIFT
// Generated by build.sh / release.sh — do not edit.
enum AppVersion {
    static let version = "$VERSION"
    static let built = "$BUILT"
    static let repo = "$REPO"
    static let updateFeed = "$FEED"
}
SWIFT
CACHE="${TMPDIR:-/tmp}/chocoedit-modcache"
mkdir -p "$CACHE" ChocoEdit.app/Contents/MacOS
cp Resources/Info.plist ChocoEdit.app/Contents/Info.plist
mkdir -p ChocoEdit.app/Contents/Resources
cp Resources/AppIcon.icns ChocoEdit.app/Contents/Resources/AppIcon.icns
/usr/libexec/PlistBuddy -c "Set :CFBundleShortVersionString $VERSION" ChocoEdit.app/Contents/Info.plist
swiftc -O -target arm64-apple-macos13 -module-cache-path "$CACHE" -suppress-warnings \
  -o ChocoEdit.app/Contents/MacOS/ChocoEdit Sources/ChocoEdit/*.swift
codesign --force --sign - ChocoEdit.app
# This build copy is for testing. Keep macOS from opening (and the updater
# from updating) it instead of the installed ~/Applications copy.
/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -u "$PWD/ChocoEdit.app" >/dev/null 2>&1 || true
swiftc -O -target arm64-apple-macos13 -module-cache-path "$CACHE" -suppress-warnings -o chocoprobe \
  Tools/chocoprobe/main.swift Sources/ChocoEdit/{SysEx,MIDI,Pedal,Layout,Keys,Errors,Version}.swift
echo "Built ChocoEdit.app and chocoprobe v$VERSION ($BUILT)"
